Below is a dependency-free TypeScript implementation that:

1. Extracts `name` and `age` from unknown input.
2. Validates that `name` is a non-empty string.
3. Validates that `age` is a finite non-negative number.
4. Returns either a valid `Person` object or a structured validation error.

```ts
export type Person = {
  name: string;
  age: number;
};

export type ValidationIssue = {
  path: string;
  code: string;
  message: string;
  received?: unknown;
  constraint?: Record<string, unknown>;
};

export type ValidationError = {
  name: "ValidationError";
  message: string;
  issues: ValidationIssue[];
};

export type ParsePersonResult =
  | { success: true; data: Person }
  | { success: false; error: ValidationError };

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function validationError(issues: ValidationIssue[]): ParsePersonResult {
  return {
    success: false,
    error: {
      name: "ValidationError",
      message: "Validation failed.",
      issues,
    },
  };
}

function parseName(raw: unknown): { value?: string; issues: ValidationIssue[] } {
  if (typeof raw !== "string") {
    return {
      issues: [
        {
          path: "name",
          code: "invalid_type",
          message: "Name must be a string.",
          received: raw,
        },
      ],
    };
  }

  const value = raw.trim();

  if (value.length === 0) {
    return {
      issues: [
        {
          path: "name",
          code: "empty_string",
          message: "Name must not be empty.",
          received: raw,
        },
      ],
    };
  }

  return { value, issues: [] };
}

function parseAge(raw: unknown): { value?: number; issues: ValidationIssue[] } {
  let candidate: number | undefined;

  if (typeof raw === "number") {
    candidate = raw;
  } else if (typeof raw === "string") {
    const trimmed = raw.trim();

    if (trimmed.length === 0) {
      return {
        issues: [
          {
            path: "age",
            code: "empty_string",
            message: "Age must not be empty when provided as a string.",
            received: raw,
          },
        ],
      };
    }

    candidate = Number(trimmed);
  } else {
    return {
      issues: [
        {
          path: "age",
          code: "invalid_type",
          message: "Age must be a number or a numeric string.",
          received: raw,
        },
      ],
    };
  }

  if (candidate === undefined || !Number.isFinite(candidate)) {
    return {
      issues: [
        {
          path: "age",
          code: "invalid_number",
          message: "Age must be a finite number.",
          received: raw,
        },
      ],
    };
  }

  if (candidate < 0) {
    return {
      issues: [
        {
          path: "age",
          code: "non_negative",
          message: "Age must be greater than or equal to 0.",
          received: candidate,
          constraint: { minimum: 0 },
        },
      ],
    };
  }

  return { value: candidate, issues: [] };
}

export function parsePerson(input: unknown): ParsePersonResult {
  if (!isRecord(input)) {
    return validationError([
      {
        path: "$",
        code: "invalid_root",
        message: "Expected an object with name and age properties.",
        received: input,
      },
    ]);
  }

  const nameResult = parseName(input.name);
  const ageResult = parseAge(input.age);

  const issues = [...nameResult.issues, ...ageResult.issues];

  if (issues.length > 0) {
    return validationError(issues);
  }

  if (nameResult.value === undefined || ageResult.value === undefined) {
    return validationError([
      {
        path: "$",
        code: "unknown",
        message: "Validation failed.",
      },
    ]);
  }

  return {
    success: true,
    data: {
      name: nameResult.value,
      age: ageResult.value,
    },
  };
}
```

Example usage:

```ts
const valid = parsePerson({ name: "Ada Lovelace", age: 36 });

if (valid.success) {
  console.log(valid.data.name);
  console.log(valid.data.age);
}
```

Example failure:

```ts
const invalid = parsePerson({ name: "Ada", age: -5 });

console.log(JSON.stringify(invalid, null, 2));
```

Result:

```json
{
  "success": false,
  "error": {
    "name": "ValidationError",
    "message": "Validation failed.",
    "issues": [
      {
        "path": "age",
        "code": "non_negative",
        "message": "Age must be greater than or equal to 0.",
        "received": -5,
        "constraint": {
          "minimum": 0
        }
      }
    ]
  }
}
```

If you need stricter validation, you can also require `age` to be an integer by replacing the finite-number check with:

```ts
if (!Number.isSafeInteger(candidate)) {
  // invalid age
}
```

