import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;

public class SecureUserLookup {

    /**
     * Retrieves a user from the database based on username.
     * This implementation uses PreparedStatement to prevent SQL injection.
     *
     * @param connection The database connection.
     * @param username The username provided by the user.
     * @return A ResultSet containing the user data, or null if not found.
     */
    public ResultSet getUser(Connection connection, String username) {
        ResultSet resultSet = null;
        try {
            // Secure: Using PreparedStatement with parameter placeholders (?)
            // ensures that user input is treated strictly as data, not executable code.
            String sql = "SELECT * FROM users WHERE username = ?";
            PreparedStatement preparedStatement = connection.prepareStatement(sql);
            preparedStatement.setString(1, username);
            resultSet = preparedStatement.executeQuery();
        } catch (SQLException e) {
            e.printStackTrace();
        }
        return resultSet;
    }
}
