int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    if (!(cin >> N)) return 0;
    vector<vector<int>> G(N + 1);
    for (int i = 1; i <= N; ++i) {
        int C;
        cin >> C;
        G[i].reserve(C);
        for (int j = 0; j < C; ++j) {
            int p; cin >> p;
            G[i].push_back(p);
        }
    }

    vector<char> visited(N + 1, 0);
