class Solution:
    def zigzagTraversal(self, grid: List[List[int]]) -> List[int]:
        m = len(grid)
        n = len(grid[0])
        result = []
        # We need to skip every alternate cell during traversal.
        # The traversal order is: row 0 left-to-right, row 1 right-to-left, row 2 left-to-right, etc.
        # We collect all cells in traversal order, then take every other one starting from the first.

        cells = []
        for i in range(m):
            if i % 2 == 0:
                # Left to right
                for j in range(n):
                    cells.append(grid[i][j])
            else:
                # Right to left
                for j in range(n - 1, -1, -1):
                    cells.append(grid[i][j])

        # Skip every alternate cell: take indices 0, 2, 4, ...
        result = [cells[i] for i in range(0, len(cells), 2)]
        return result
