## Solution

We number cuts modulo `N`. Starting from a cut, the pieces are read clockwise.

For a threshold `X`, define for every cut `i`:

- `nxt[i]`: the first cut reached clockwise such that the pieces from `i` to `nxt[i]` have total mass at least `X`.
- `len[i]`: the number of pieces in that shortest interval.

Because all masses are positive, if we want `K` consecutive blocks each of mass at least `X`, choosing the shortest possible first block is always optimal. Thus, starting from cut `i`, the minimum possible total number of pieces consumed by `K` blocks is obtained by following `nxt` exactly `K` times and summing the corresponding `len`.

A division with minimum mass at least `X` exists starting from cut `i` **iff** this `K`-step total length is at most `N`.  
A cut line is used in some optimal division iff it is feasible as a starting cut for `x = answer`.

So we need:

1. Maximize `X` such that some cut has `K`-step length `<= N`.
2. For the maximum `x`, count cuts whose `K`-step length is `> N`.

For a fixed `X`, the graph `i -> nxt[i]` is a functional graph with edge weights `len[i]`. We need the sum of weights along `K` edges from every node. This can be done in `O(N)` by decomposing the functional graph into cycles and trees:

- Find cycles by Kahn removal of non-cycle nodes.
- For each cycle, use doubled prefix sums to get cycle walk sums in `O(1)`.
- For trees feeding into cycles, DFS backwards from cycle nodes while maintaining depth and prefix sums to the cycle.  
  For a tree node at depth `d` with sum `s` to its cycle root:
  - If `K <= d`, the `K` steps stay inside the tree: answer is `s - sum[ancestor at depth d-K]`.
  - Otherwise, answer is `s +` cycle sum for `K-d` steps from the root.

Then binary search `x`.

`x <= total_mass / K`, so binary search needs at most 31 iterations.

**Complexity:** `O(N log(total_mass/K))` time, `O(N)` memory.

```cpp
#include <bits/stdc++.h>
using namespace std;

using ll = long long;

int N, K;
vector<ll> pref;

vector<int> nxt, wt, indeg, revHead, revNext, que;
vector<unsigned char> state; // 0: tree, 1: unprocessed cycle, 2: processed cycle, 3: visited tree

vector<int> cyc;
vector<ll> cycPref, pathSum;

struct Frame {
    int edge;
    int depth;
    ll sum;
};
vector<Frame> stk;

// countMode == false: return 1 if feasible, else 0 (early exit)
// countMode == true : return number of infeasible cuts
int process(ll x, bool countMode) {
    // Build nxt and wt.
    int j = 0;
    for (int i = 0; i < N; ++i) {
        if (j < i + 1) j = i + 1;
        int limit = i + N;
        while (j <= limit && pref[j] - pref[i] < x) ++j;

        if (j <= limit) {
            wt[i] = j - i;
            int v = j;
            if (v >= N) v -= N;
            if (v >= N) v -= N; // safety
            nxt[i] = v;
        } else {
            // Should not happen for x <= total / K, but kept safe.
            wt[i] = N + 1;
            nxt[i] = i;
        }
    }

    // Build reversed graph and indegrees.
    fill(indeg.begin(), indeg.end(), 0);
    fill(revHead.begin(), revHead.end(), -1);
    for (int i = 0; i < N; ++i) {
        int v = nxt[i];
        ++indeg[v];
        revNext[i] = revHead[v];
        revHead[v] = i;
    }

    // Kahn: remove non-cycle nodes.
    fill(state.begin(), state.end(), 1);
    int qh = 0, qt = 0;
    for (int i = 0; i < N; ++i) {
        if (indeg[i] == 0) {
            state[i] = 0;
            que[qt++] = i;
        }
    }
    while (qh < qt) {
        int u = que[qh++];
        int v = nxt[u];
        if (--indeg[v] == 0) {
            state[v] = 0;
            que[qt++] = v;
        }
    }

    int feasibleCount = 0;

    // Process each cycle and its trees.
    for (int i = 0; i < N; ++i) {
        if (state[i] != 1) continue;

        cyc.clear();
        int u = i;
        do {
            cyc.push_back(u);
            state[u] = 2;
            u = nxt[u];
        } while (u != i);

        int L = (int)cyc.size();

        cycPref.resize(2 * L + 1);
        cycPref[0] = 0;
        for (int t = 0; t < 2 * L; ++t) {
            cycPref[t + 1] = cycPref[t] + wt[cyc[t % L]];
        }

        ll cycleTotal = cycPref[L];
        int qK = K / L;
        int rK = K % L;

        // Cycle nodes.
        for (int t = 0; t < L; ++t) {
            ll ans = (ll)qK * cycleTotal + (cycPref[t + rK] - cycPref[t]);
            if (ans <= N) {
                if (!countMode) return 1;
                ++feasibleCount;
            }
        }

        // Trees attached to each cycle node.
        for (int t = 0; t < L; ++t) {
            int root = cyc[t];

            pathSum.clear();
            pathSum.push_back(0); // depth 0: cycle root, sum to cycle = 0

            stk.clear();
            stk.push_back({revHead[root], 0, 0});

            while (!stk.empty()) {
                int edge = stk.back().edge;
                int depth = stk.back().depth;
                ll sum = stk.back().sum;

                if (edge == -1) {
                    stk.pop_back();
                    pathSum.resize(depth + 1);
                    continue;
                }

                stk.back().edge = revNext[edge];

                if (state[edge] != 0) continue; // skip cycle/already visited nodes

                int child = edge;
                state[child] = 3; // visited tree node

                int d = depth + 1;
                ll s = sum + wt[child];

                if ((int)pathSum.size() <= d) pathSum.resize(d + 1);
                pathSum[d] = s;

                ll ans;
                if (K <= d) {
                    // K steps stay inside the tree.
                    ans = s - pathSum[d - K];
                } else {
                    // Go to cycle, then walk on cycle.
                    int rem = K - d;
                    int q = rem / L;
                    int r = rem % L;
                    ll cyclePart = (ll)q * cycleTotal + (cycPref[t + r] - cycPref[t]);
                    ans = s + cyclePart;
                }

                if (ans <= N) {
                    if (!countMode) return 1;
                    ++feasibleCount;
                }

                stk.push_back({revHead[child], d, s});
            }
        }
    }

    if (!countMode) return 0;
    return N - feasibleCount;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N >> K;

    vector<int> A(N);
    ll total = 0;
    for (int i = 0; i < N; ++i) {
        cin >> A[i];
        total += A[i];
    }

    pref.assign(2 * N + 1, 0);
    for (int i = 0; i < 2 * N; ++i) {
        pref[i + 1] = pref[i] + A[i % N];
    }

    nxt.resize(N);
    wt.resize(N);
    indeg.resize(N);
    revHead.resize(N);
    revNext.resize(N);
    state.resize(N);
    que.resize(N);

    cyc.reserve(N);
    cycPref.reserve(2 * N + 1);
    pathSum.reserve(N + 1);
    stk.reserve(N);

    ll low = 1, high = total / K, ans = 0;
    while (low <= high) {
        ll mid = (low + high) / 2;
        if (process(mid, false)) {
            ans = mid;
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }

    int y = process(ans, true);
    cout << ans << ' ' << y << '\n';

    return 0;
}
```

## Solution

The minimum tree is exactly the smallest connected subgraph of the given tree that contains all specified vertices.  
In a tree, this subgraph is unique: it is the union of all paths between specified vertices.

A useful observation is:

> An edge is necessary in the minimum Steiner tree if and only if, after removing that edge, both resulting components contain at least one specified vertex.

If one side contains no specified vertices, that whole side can be removed.  
If both sides contain specified vertices, the tree must connect them, so the edge must remain.

Therefore:

\[
\text{answer} = (\text{number of necessary edges}) + 1
\]

because the remaining necessary edges form a non-empty tree.

---

## Algorithm

Root the original tree at vertex `1`.

Let `cnt[v]` be the number of specified vertices in the subtree of `v`.

For every non-root vertex `v`, the edge connecting `v` to its parent splits the tree into:

- the subtree of `v`, containing `cnt[v]` specified vertices;
- the rest of the tree, containing `K - cnt[v]` specified vertices.

So that edge is necessary iff:

\[
0 < cnt[v] < K
\]

We can compute all `cnt[v]` with one iterative DFS.

---

## Complexity

- Time: `O(N)`
- Memory: `O(N)`

---

## C++ Implementation

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, K;
    cin >> N >> K;

    vector<vector<int>> graph(N + 1);

    for (int i = 0; i < N - 1; i++) {
        int A, B;
        cin >> A >> B;
        graph[A].push_back(B);
        graph[B].push_back(A);
    }

    vector<int> cnt(N + 1, 0);

    for (int i = 0; i < K; i++) {
        int v;
        cin >> v;
        cnt[v] = 1;
    }

    // Build parent array and traversal order iteratively.
    vector<int> parent(N + 1, 0);
    vector<int> order;
    order.reserve(N);

    vector<int> stack;
    stack.push_back(1);
    parent[1] = -1;

    while (!stack.empty()) {
        int v = stack.back();
        stack.pop_back();

        order.push_back(v);

        for (int to : graph[v]) {
            if (to == parent[v]) continue;
            parent[to] = v;
            stack.push_back(to);
        }
    }

    int necessary_edges = 0;

    // Process vertices in reverse preorder, so children are processed before parents.
    for (int i = N - 1; i >= 0; i--) {
        int v = order[i];

        if (v == 1) continue;

        if (0 < cnt[v] && cnt[v] < K) {
            necessary_edges++;
        }

        cnt[parent[v]] += cnt[v];
    }

    cout << necessary_edges + 1 << '\n';

    return 0;
}
```

We can compute the total by counting each position’s contribution.

For a subarray `[l, r]`, each distinct value has exactly one **first occurrence** inside that subarray.  
So instead of computing `f(l, r)` for every subarray, count for each index `i` how many subarrays have `A_i` as the first occurrence of its value.

Let `last[x]` be the previous position of value `x`, or `0` if it has not appeared yet.

For position `i`:

- The left endpoint `l` must be after the previous same value: `last[A_i] < l <= i`
  - choices: `i - last[A_i]`
- The right endpoint `r` can be anywhere from `i` to `N`
  - choices: `N - i + 1`

So position `i` contributes:

\[
(i - last[A_i]) \times (N - i + 1)
\]

Sum this over all `i`.

---

