from typing import List

class Solution:
    def maximumSubarraySum(self, nums: List[int], k: int) -> int:
        # min_prefix[value] = minimum prefix sum before an index i
        # where nums[i] == value
        min_prefix = {}
        prefix = 0
        ans = None

        for x in nums:
            # Prefix sum after including current element x
            cur_prefix = prefix + x

            # If current x is the last element, first element must be x-k or x+k
            for target in (x - k, x + k):
                if target in min_prefix:
                    ans = max(
                        ans if ans is not None else float("-inf"),
                        cur_prefix - min_prefix[target]
                    )

            # Current index can be a future starting index
            if x not in min_prefix or prefix < min_prefix[x]:
                min_prefix[x] = prefix

            prefix = cur_prefix

        return 0 if ans is None else ans
