using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<long long> A(N);
    for (int i = 0; i < N; i++) {
        cin >> A[i];
    }

    long long ans = 0;
    long long len = 0;

    for (int i = 0; i < N; i++) {
        if (i == 0) {
            len = 1;
        } else if (i == 1) {
            len = 2;
        } else {
            long long d1 = A[i] - A[i - 1];
            long long d2 = A[i - 1] - A[i - 2];

            if (d1 == d2) {
                len++;
            } else {
                len = 2;
            }
        }

        ans += len;
    }

    cout << ans << '\n';

    return 0;
}
