```cpp
#include <iostream>
#include <vector>
#include <map>
#include <set>
#include <algorithm>
#include <string>

using namespace std;

int main() {
    // Optimize I/O
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    long long Sx, Sy;
    if (!(cin >> N >> M >> Sx >> Sy)) return 0;

    // Map to store houses grouped by x-coordinate (for vertical moves)
    // Key: x, Value: sorted vector of y-coordinates
    map<long long, vector<long long>> houses_by_x;

    // Map to store houses grouped by y-coordinate (for horizontal moves)
    // Key: y, Value: sorted vector of x-coordinates
    map<long long, vector<long long>> houses_by_y;

    for (int i = 0; i < N; ++i) {
        long long x, y;
        cin >> x >> y;
        houses_by_x[x].push_back(y);
        houses_by_y[y].push_back(x);
    }

    // Sort the vectors to enable binary search
    for (auto &p : houses_by_x) {
        sort(p.second.begin(), p.second.end());
    }
    for (auto &p : houses_by_y) {
        sort(p.second.begin(), p.second.end());
    }

    long long cur_x = Sx;
    long long cur_y = Sy;

    // Set to keep track of distinct houses visited
    set<pair<long long, long long>> visited_houses;

    for (int i = 0; i < M; ++i) {
        char D;
        long long C;
        cin >> D >> C;

        long long start_x = cur_x;
        long long start_y = cur_y;

        if (D == 'U') {
            cur_y += C;
        } else if (D == 'D') {
            cur_y -= C;
        } else if (D == 'L') {
            cur_x -= C;
        } else if (D == 'R') {
            cur_x += C;
        }

        long long end_x = cur_x;
        long long end_y = cur_y;

        // Check for houses on the segment from (start_x, start_y) to (end_x, end_y)
        if (start_x == end_x) {
            // Vertical move
            long long x = start_x;
            long long min_y = min(start_y, end_y);
            long long max_y = max(start_y, end_y);

            // Check if there are any houses with this x-coordinate
            auto it = houses_by_x.find(x);
            if (it != houses_by_x.end()) {
                const vector<long long>& ys = it->second;

                // Find the first y >= min_y
                auto lower_it = lower_bound(ys.begin(), ys.end(), min_y);
                // Find the first y > max_y
                auto upper_it = upper_bound(ys.begin(), ys.end(), max_y);

                // Iterate through the houses in this range
                for (auto it_y = lower_it; it_y != upper_it; ++it_y) {
                    long long y = *it_y;
                    visited_houses.insert({x, y});
                }
            }
        } else if (start_y == end_y) {
            // Horizontal move
            long long y = start_y;
            long long min_x = min(start_x, end_x);
            long long max_x = max(start_x, end_x);

            // Check if there are any houses with this y-coordinate
            auto it = houses_by_y.find(y);
            if (it != houses_by_y.end()) {
                const vector<long long>& xs = it->second;

                // Find the first x >= min_x
                auto lower_it = lower_bound(xs.begin(), xs.end(), min_x);
                // Find the first x > max_x
                auto upper_it = upper_bound(xs.begin(), xs.end(), max_x);

                // Iterate through the houses in this range
                for (auto it_x = lower_it; it_x != upper_it; ++it_x) {
                    long long x = *it_x;
                    visited_houses.insert({x, y});
                }
            }
        }
    }

    cout << cur_x << " " << cur_y << " " << visited_houses.size() << endl;

    return 0;
}
